  // …
}
```

#### 2️⃣ Guard the tick loop

```ts
private tick(): void {
  // If we are currently trying to reconnect, do nothing.
  if (this.reconnecting) return;
  if (!this.simulation || this.phase !== "running") return;
  // … rest of the method unchanged …
}
```

#### 3️⃣ Guard the scheduler

```ts
private async runScheduler(): Promise<void> {
  if (!this.simulation || this.phase !== "running" || this.paused) return;
  if (!this.connected) return;
  if (this.activeTurn || this.autoplayLocked) return;
  if (this.reconnecting) return;               // <‑‑ NEW

  const agentId = this.nextSchedulableAgentId();
  // …
}
```

